117	// Owns the descriptor opened for the newly created key file for the duration
118	// of one save attempt and closes it exactly once. Closing is centralized here
119	// rather than spread across the failure branches: a branch only records its
120	// reason, and the descriptor is still released on every path out of scope.
121	class FdGuard {
122	public:
123	    FdGuard() = default;
124	    explicit FdGuard(int fd) : fd_(fd) {}
125	    ~FdGuard() { close(); }
126	
127	    FdGuard(const FdGuard&) = delete;
128	    FdGuard& operator=(const FdGuard&) = delete;
129	    FdGuard(FdGuard&&) = delete;
130	    FdGuard& operator=(FdGuard&&) = delete;
131	
132	    // Closes and disarms the guard, reporting close(2)'s status. Used after
133	    // fsync(), where a reported failure means durability could not be
134	    // confirmed and success must not be reported. Must be called while armed.
135	    int finish() {
136	        const int fd = fd_;
137	        fd_ = -1;
138	        return ::close(fd);
139	    }
140	
141	    // Best-effort close for failure paths: the save has already failed, and
142	    // close(2) releases the descriptor even when it reports an error, so the
143	    // result is intentionally discarded here. Idempotent via disarming.
144	    void close() {
145	        if (fd_ != -1) {
146	            const int fd = fd_;
147	            fd_ = -1;
148	            ::close(fd);
149	        }
150	    }
151	
152	private:
153	    int fd_ = -1;
154	};
