184	// Creates a brand new file containing exactly keySize raw bytes. Any existing
185	// path (file, directory, symlink including a dangling one) is rejected. The
186	// file is created with mode 0600 and its permissions are then forced to
187	// exactly 0600 (the creation mode alone is still subject to the umask) before
188	// any key byte is written; at no point is the file accessible to group or
189	// other users.
190	//
191	// The outcome is reported entirely through KeySaveResult: an open() failure
192	// creates nothing (kNotCreated); a failure after creation closes the
193	// descriptor via the FdGuard and removes this run's file, reporting either
194	// kCleanedUp or, if the removal itself failed, kCleanupFailed with the
195	// removal reason in removalWarning so the caller can warn that an incomplete
196	// key file may remain. This function never writes to stdout or stderr.
197	KeySaveResult writeKeyFile(const std::string& path,
198	                           const unsigned char* key,
199	                           std::size_t keySize) {
200	    KeySaveResult result;
201	
202	    int fd = ::open(path.c_str(),
203	                    O_WRONLY | O_CREAT | O_EXCL | O_NOFOLLOW,
204	                    S_IRUSR | S_IWUSR);
205	    if (fd == -1) {
206	        const int savedErrno = errno;
207	        // Pre-creation failure: nothing was created, so this must not enter
208	        // the "remove the new file" handling and an existing target's
209	        // content, permissions, and links are never touched.
210	        result.status = KeySaveStatus::kNotCreated;
211	        if (savedErrno == EEXIST || savedErrno == ELOOP) {
212	            result.error = "refusing to write, path already exists: " + path;
213	        } else {
214	            result.error = "cannot create key file '" + path + "': " +
215	                           errnoDescription(savedErrno);
216	        }
217	        return result;
218	    }
219	
220	    FdGuard guard(fd);
221	    result.status = KeySaveStatus::kCleanedUp;  // assumed until the save completes
222	    std::string error;
223	
224	    // If the permissions cannot be guaranteed, this run must not be reported
225	    // as a success even though the key was generated and the file was
226	    // created: skip the write and fall through to the cleanup below, before
227	    // any key byte reaches the file.
228	    if (fixKeyFilePermissions(fd, path, error)) {
229	        std::size_t totalWritten = 0;
230	        while (totalWritten < keySize) {
231	            ssize_t written =
232	                ::write(fd, key + totalWritten, keySize - totalWritten);
233	            if (written < 0) {
234	                if (errno == EINTR) {
235	                    continue;
236	                }
237	                error = "failed writing key file '" + path + "': " +
238	                        errnoDescription(errno);
239	                break;
240	            }
241	            if (written == 0) {
242	                error = "failed writing key file '" + path + "': short write";
243	                break;
244	            }
245	            totalWritten += static_cast<std::size_t>(written);
246	        }
247	
248	        if (totalWritten == keySize) {
249	            if (::fsync(fd) != 0) {
250	                error = "failed syncing key file '" + path + "': " +
251	                        errnoDescription(errno);
252	            } else if (guard.finish() != 0) {
253	                // The descriptor is closed by the kernel even when close
254	                // fails, but durability could not be confirmed: do not
255	                // report success.
256	                error = "failed closing key file '" + path + "': " +
257	                        errnoDescription(errno);
258	            } else {
259	                // The complete original key is written, synced, and closed;
260	                // 0600 was verified before the first byte.
261	                result.status = KeySaveStatus::kSaved;
262	                result.error.clear();
263	                return result;
264	            }
265	        }
266	    }
267	
268	    // Failure after creation. The descriptor opened by this run is closed
269	    // exactly once (guard.finish() above already disarmed it on the
270	    // close-failure path); removing the path cannot touch prior content
271	    // because O_EXCL guaranteed the file did not exist before open().
272	    guard.close();
273	    if (::unlink(path.c_str()) != 0 && errno != ENOENT) {
274	        // The original save failure remains the reported cause; this only
275	        // adds that the incomplete file could not be removed.
276	        result.status = KeySaveStatus::kCleanupFailed;
277	        result.removalWarning =
278	            "could not remove partial key file '" + path + "': " +
279	            errnoDescription(errno);
280	    }
281	    result.error = std::move(error);
282	    return result;
283	}
