249	// On the first key-file write, snapshot the key; afterwards confirm that the
250	// caller resumes exactly at the acknowledged offset and presents the matching
251	// slice of the same key. Every call must also pass a pointer into the very
252	// buffer RAND_bytes filled (at the current offset): the bytes reaching the
253	// file are then provably the ones OPENSSL_cleanse later wipes, not an
254	// unwiped copy. Any mismatch is a product-code defect: abort so the
255	// regression run can never pass on a silently regenerated/garbled key.
256	void verifyIncomingBuffer(const void* buffer, std::size_t count) {
257	    if (std::getenv("EF_TEST_WRITE_LOG") == nullptr) {
258	        return;
259	    }
260	    const auto* bytes = static_cast<const unsigned char*>(buffer);
261	    if (g_randBuf != nullptr && bytes != g_randBuf + g_progress) {
262	        logVerifyFailed("write buffer is not the buffer filled by RAND_bytes");
263	        std::abort();
264	    }
265	    if (!g_haveSnapshot) {
266	        if (count != kKeyBytes) {
267	            logVerifyFailed("first write did not carry the whole 32-byte key");
268	            std::abort();
269	        }
270	        std::memcpy(g_keySnapshot, bytes, kKeyBytes);
271	        g_haveSnapshot = true;
272	        logVerifyHeader(g_keySnapshot);
273	        return;
274	    }
275	    if (g_progress > kKeyBytes) {
276	        logVerifyFailed("offset past end of key");
277	        std::abort();
278	    }
279	    const std::size_t remaining = kKeyBytes - g_progress;
280	    if (count != remaining) {
281	        logVerifyFailed("write length does not match the bytes still pending");
282	        std::abort();
283	    }
284	    if (std::memcmp(g_keySnapshot + g_progress, bytes, remaining) != 0) {
285	        logVerifyFailed("buffer is not the same key (key was regenerated?)");
286	        std::abort();
287	    }
288	}
