295	// Outcome of one scripted write() call.
296	enum class WriteOutcome {
297	    kPass,       // behave as the real syscall with the given count
298	    kShort,      // behave as the real syscall but cap the count
299	    kEintr,      // report a recoverable interrupt, nothing written
300	    kEio,        // report an irrecoverable I/O error
301	    kZero,       // report zero bytes with data still pending
