309	// Parse the next EF_TEST_WRITE_SCRIPT token. Returns false once the script is
310	// exhausted (the caller should then behave normally).
311	bool nextScriptedCall(ScriptedCall& call) {
312	    static char script[512];
313	    static bool initialized = false;
314	    static char* saveptr = nullptr;
315	
316	    if (!initialized) {
317	        const char* raw = std::getenv("EF_TEST_WRITE_SCRIPT");
318	        if (raw == nullptr) {
319	            script[0] = '\0';
320	        } else {
321	            std::strncpy(script, raw, sizeof(script) - 1);
322	            script[sizeof(script) - 1] = '\0';
323	        }
324	        saveptr = script;
325	        initialized = true;
326	    }
327	
328	    char* token = ::strtok_r(nullptr, ",", &saveptr);
329	    if (token == nullptr) {
330	        return false;
331	    }
332	    if (std::strcmp(token, "ok") == 0) {
333	        call.outcome = WriteOutcome::kPass;
334	    } else if (std::strcmp(token, "intr") == 0) {
335	        call.outcome = WriteOutcome::kEintr;
336	    } else if (std::strcmp(token, "eio") == 0) {
337	        call.outcome = WriteOutcome::kEio;
338	    } else if (std::strcmp(token, "zero") == 0) {
339	        call.outcome = WriteOutcome::kZero;
340	    } else {
341	        char* end = nullptr;
342	        long limit = std::strtol(token, &end, 10);
343	        if (end != token && *end == '\0' && limit > 0) {
344	            call.outcome = WriteOutcome::kShort;
345	            call.limit = limit;
346	        } else {
347	            // An unknown token is a test-script bug: fail loudly rather than
348	            // silently behave as a normal write.
349	            std::fprintf(stderr,
350	                         "envelopefile_testable: invalid write script token "
351	                         "'%s'\n", token);
352	            call.outcome = WriteOutcome::kEio;
353	        }
354	    }
355	    return true;
356	}
