396	    const int result = __real_fstat(fd, info);
397	    if (result == 0) {
398	        const char* forced = std::getenv("EF_TEST_FSTAT_MODE");
399	        if (forced != nullptr && forced[0] != '\0') {
400	            char* end = nullptr;
401	            const unsigned long forcedMode = std::strtoul(forced, &end, 8);
402	            if (end != forced && *end == '\0') {
403	                // Keep the file-type bits; replace only the permission bits
404	                // the product code verifies against exactly 0600.
