414	ssize_t __wrap_write(int fd, const void* buffer, size_t count) {
415	    if (!isKeyFd(fd)) {
416	        return __real_write(fd, buffer, count);
417	    }
418	
419	    verifyIncomingBuffer(buffer, count);
420	
421	    const size_t requested = count;  // caller's original length for the log
422	    ScriptedCall call;
423	    const bool scripted = nextScriptedCall(call);
424	    if (scripted) {
425	        switch (call.outcome) {
426	            case WriteOutcome::kEintr:
427	                logCall(g_progress, requested, -1, EINTR);
428	                errno = EINTR;
429	                return -1;
430	            case WriteOutcome::kEio:
431	                logCall(g_progress, requested, -1, EIO);
432	                errno = EIO;
433	                return -1;
434	            case WriteOutcome::kZero:
435	                logCall(g_progress, requested, 0, 0);
436	                errno = 0;
437	                return 0;
438	            case WriteOutcome::kShort:
439	                if (count > static_cast<size_t>(call.limit)) {
440	                    count = static_cast<size_t>(call.limit);
441	                }
442	                break;
443	            case WriteOutcome::kPass:
444	                break;
445	        }
446	    } else {
447	        // Legacy single-knob injection, kept for the existing regressions.
448	        if (envFlagSet("EF_TEST_FAIL_WRITE")) {
449	            logCall(g_progress, requested, -1, EIO);
450	            errno = EIO;
451	            return -1;
452	        }
453	        const char* chunk = std::getenv("EF_TEST_PARTIAL_WRITE");
454	        if (chunk != nullptr) {
455	            const long limit = std::atol(chunk);
456	            if (limit > 0 && count > static_cast<size_t>(limit)) {
457	                count = static_cast<size_t>(limit);
458	            }
459	        }
460	    }
461	
462	    ssize_t result = __real_write(fd, buffer, count);
463	    logCall(g_progress, requested, result, errno);
464	    if (result > 0) {
465	        g_progress += static_cast<std::size_t>(result);
466	    }
467	    return result;
468	}
