493	int __wrap_unlink(const char* path) {
494	    // Only the cleanup of the file this run created can be faulted, so a
495	    // simulated failure never blocks removal of (or any operation on) an
496	    // unrelated path — the product code only ever unlinks the O_EXCL-created
497	    // key path, and this matches the injection to exactly that name.
498	    if (path != nullptr && g_keyPath[0] != '\0' &&
499	        std::strcmp(path, g_keyPath) == 0 &&
500	        envFlagSet("EF_TEST_FAIL_UNLINK")) {
501	        errno = EIO;
502	        return -1;
503	    }
504	    return __real_unlink(path);
505	}
