507	int __wrap_RAND_bytes(unsigned char* buf, int num) {
508	    if (!envFlagSet("EF_TEST_FAIL_RAND")) {
509	        const int result = __real_RAND_bytes(buf, num);
510	        if (result == 1) {
511	            g_randBuf = buf;
512	            g_randBufSize = num;
513	            char line[96];
514	            std::snprintf(line, sizeof(line),
515	                          "RAND %d partial=0 result=ok", num);
516	            logKeyLine(line);
517	        }
518	        return result;
519	    }
520	
521	    g_randBuf = buf;
522	    g_randBufSize = num;
523	
524	    // Simulate a CSPRNG that wrote some bytes before dying: the caller must
525	    // not mistake the partial fill for a valid key.
526	    long partial = 0;
527	    const char* raw = std::getenv("EF_TEST_RAND_PARTIAL");
528	    if (raw != nullptr) {
529	        partial = std::atol(raw);
530	        if (partial < 0) {
531	            partial = 0;
532	        }
533	        if (partial > num) {
534	            partial = num;
535	        }
536	    }
537	    for (long i = 0; i < partial; ++i) {
538	        buf[i] = 0xA5;
539	    }
540	
541	    // Start from an empty error queue, then optionally leave a descriptive
542	    // OpenSSL error so the "detail" and "no detail" messages are both
543	    // exercised deterministically.
544	    ERR_clear_error();
545	    if (envFlagSet("EF_TEST_RAND_ERROR_DETAIL")) {
546	#if OPENSSL_VERSION_NUMBER >= 0x30000000L
547	        ERR_raise(ERR_LIB_RAND, 0x7f);
548	#else
549	        ERR_put_error(ERR_LIB_RAND, 0, 0x7f, __FILE__, __LINE__);
550	#endif
551	    }
552	
553	    char line[96];
554	    std::snprintf(line, sizeof(line), "RAND %d partial=%ld result=fail",
555	                  num, partial);
556	    logKeyLine(line);
557	    return 0;
558	}
559	
560	void __wrap_OPENSSL_cleanse(void* ptr, size_t len) {
561	    if (ptr != nullptr && ptr == g_randBuf) {
562	        char line[96];
563	        std::snprintf(line, sizeof(line), "CLEANSED-KEY %zu", len);
564	        logKeyLine(line);
565	        // Record how far the save had progressed when the wipe happened, so
566	        // the test driver can prove a successful save was not preceded by
567	        // the wipe (which would have saved wiped data).
568	        char state[96];
569	        std::snprintf(state, sizeof(state),
570	                      "CLEANSE-STATE writes=%zu keyfd=%s",
571	                      g_progress, g_keyFd == -1 ? "closed" : "open");
572	        logKeyLine(state);
573	        // The buffer is about to be released; do not match a stale address.
574	        g_randBuf = nullptr;
575	        g_randBufSize = 0;
576	    }
577	    __real_OPENSSL_cleanse(ptr, len);
578	}
579	
580	}  // extern "C"
